import{_ as u,C as r,c as n,o as i,a2 as t,b as s,w as o,a as c,G as p,a3 as l}from"./chunks/framework.DkPtUiZm.js";const f=JSON.parse('{"title":"Contribution publique","description":"","frontmatter":{},"headers":[],"relativePath":"contribuer/contribution-publique.md","filePath":"contribuer/contribution-publique.md","lastUpdated":1791456341000}'),d={name:"contribuer/contribution-publique.md"};function b(m,e,q,v,h,_){const a=r("Mermaid");return i(),n("div",null,[e[1]||(e[1]=t('<h1 id="contribution-publique" tabindex="-1">Contribution publique <a class="header-anchor" href="#contribution-publique" aria-label="Permalink to &quot;Contribution publique&quot;">​</a></h1><p>Le dépôt source de SIA UI reste privé pour le moment. La contribution publique ne commence donc pas par une pull request sur le code, mais par un retour structuré dans le dépôt public <code>BeatJo/sia-ui-site</code>.</p><p>Ce dépôt public sert de guichet pour :</p><ul><li>signaler un bug rencontré avec un paquet npm ou un composant copié par la CLI;</li><li>demander un composant, une variante ou un comportement;</li><li>corriger ou clarifier la documentation publiée;</li><li>poser une question d&#39;usage.</li></ul><p>Les contributions directes au code des packages (<code>@sia-ui/react-web</code>, <code>@sia-ui/cli</code>, <code>@sia-ui/headless</code>, etc.) se font sur invitation dans le dépôt source privé.</p><h2 id="parcours" tabindex="-1">Parcours <a class="header-anchor" href="#parcours" aria-label="Permalink to &quot;Parcours&quot;">​</a></h2>',6)),(i(),s(l,null,{default:o(()=>[p(a,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20User%5B%22Utilisateur%20npm%22%5D%20--%3E%20Public%5B%22Issue%20publique%3Cbr%2F%3EBeatJo%2Fsia-ui-site%22%5D%0A%20%20Public%20--%3E%20Triage%5B%22Tri%3Cbr%2F%3Ebug%2C%20composant%2C%20documentation%22%5D%0A%20%20Triage%20--%3E%20Private%5B%22Correction%20ou%20d%C3%A9cision%3Cbr%2F%3Ed%C3%A9p%C3%B4t%20priv%C3%A9%20sia-ui%22%5D%0A%20%20Private%20--%3E%20Release%5B%22Publication%3Cbr%2F%3Enpm%20%2B%20site%22%5D%0A%20%20Release%20--%3E%20User%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="ce-que-voit-un-utilisateur" tabindex="-1">Ce que voit un utilisateur <a class="header-anchor" href="#ce-que-voit-un-utilisateur" aria-label="Permalink to &quot;Ce que voit un utilisateur&quot;">​</a></h2><p>Depuis npm, les champs des paquets envoient vers les surfaces publiques :</p><ul><li><code>homepage</code> pointe vers la documentation et la démonstration publiées;</li><li><code>bugs.url</code> pointe vers les issues du dépôt public;</li><li><code>repository</code> pointe vers le dépôt public de contribution tant que le dépôt source reste privé.</li></ul><p>Le README de chaque paquet rappelle aussi cette règle : les retours sont publics, le code source principal est privé, et les contributions code directes se font sur invitation.</p><h2 id="gabarits-a-mettre-dans-le-depot-public" tabindex="-1">Gabarits à mettre dans le dépôt public <a class="header-anchor" href="#gabarits-a-mettre-dans-le-depot-public" aria-label="Permalink to &quot;Gabarits à mettre dans le dépôt public&quot;">​</a></h2><p>Le dépôt public porte les gabarits d&#39;issues adaptés aux utilisateurs :</p><ul><li><code>anomalie.yml</code> pour un bug de composant, de paquet ou de CLI;</li><li><code>composant.yml</code> pour demander une nouvelle entrée ou une variante;</li><li><code>documentation.yml</code> pour une page confuse, un exemple cassé ou un lien mort.</li></ul><p>Ces fichiers vivent dans <code>public-repo/.github/ISSUE_TEMPLATE/</code>. Le script <code>scripts/synchroniser-depot-public.mjs</code> les copie dans <code>.pages/</code>, et le workflow Pages pousse ensuite <code>.pages/</code> vers <code>BeatJo/sia-ui-site</code>.</p><p>Le dépôt public ne doit donc pas être corrigé à la main : une modification du processus de contribution se fait ici, dans le dépôt source, puis voyage à la publication suivante.</p><h2 id="quand-inviter-quelqu-un-au-depot-prive" tabindex="-1">Quand inviter quelqu&#39;un au dépôt privé <a class="header-anchor" href="#quand-inviter-quelqu-un-au-depot-prive" aria-label="Permalink to &quot;Quand inviter quelqu&#39;un au dépôt privé&quot;">​</a></h2><p>Une invitation au dépôt source se justifie seulement si la personne doit modifier le code réel : composants, CLI, registre, packages, tests ou documentation source. Un bug report, une demande de composant ou une capture d&#39;écran ne nécessite pas cet accès.</p><h2 id="reponse-type" tabindex="-1">Réponse type <a class="header-anchor" href="#reponse-type" aria-label="Permalink to &quot;Réponse type&quot;">​</a></h2><p>Quand quelqu&#39;un demande comment contribuer, répondre :</p><blockquote><p>Merci. Le code source principal est privé pour le moment. Ouvre une issue sur <code>BeatJo/sia-ui-site</code> avec le gabarit adapté : bug, demande de composant ou documentation. Si une contribution code devient nécessaire, je t&#39;inviterai au dépôt source.</p></blockquote>',14))])}const C=u(d,[["render",b]]);export{f as __pageData,C as default};
